export function roundedNoteGeometry(THREE){const s=new THREE.Shape(),r=.19;s.moveTo(-.5+r,-.5);s.lineTo(.5-r,-.5);s.quadraticCurveTo(.5,-.5,.5,-.5+r);s.lineTo(.5,.5-r);s.quadraticCurveTo(.5,.5,.5-r,.5);s.lineTo(-.5+r,.5);s.quadraticCurveTo(-.5,.5,-.5,.5-r);s.lineTo(-.5,-.5+r);s.quadraticCurveTo(-.5,-.5,-.5+r,-.5);const g=new THREE.ExtrudeGeometry(s,{depth:.6,bevelEnabled:true,bevelSize:.075,bevelThickness:.12,bevelSegments:4,steps:1,curveSegments:5});g.rotateX(-Math.PI/2);g.translate(0,-.3,0);g.scale(1/1.15,1/.84,1/1.15);return g;}
export function createStudio(THREE){const group=new THREE.Group();group.name='studio-ground';const floor=new THREE.Mesh(new THREE.CircleGeometry(10,96),new THREE.MeshPhysicalMaterial({color:0x2c243a,roughness:.36,metalness:.19,clearcoat:.5,clearcoatRoughness:.2}));floor.rotation.x=-Math.PI/2;floor.position.y=-.25;floor.receiveShadow=true;group.add(floor);
 for(const [radius,color,opacity] of [[2.8,0xbba0bf,.13],[4.4,0x83bfd1,.07]]){const ring=new THREE.Mesh(new THREE.TorusGeometry(radius,.004,5,140),new THREE.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false}));ring.rotation.x=Math.PI/2;ring.position.set(0,-.247,-.1);ring.scale.set(1,.54,1);group.add(ring);}
 return group;}
export function createSparkles(THREE){const canvas=document.createElement('canvas');canvas.width=64;canvas.height=64;const ctx=canvas.getContext('2d');const g=ctx.createRadialGradient(32,32,0,32,32,30);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.12,'rgba(255,246,221,.95)');g.addColorStop(.3,'rgba(255,234,209,.23)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,64,64);ctx.fillStyle='rgba(255,255,255,.7)';ctx.beginPath();ctx.moveTo(32,15);ctx.quadraticCurveTo(34,30,49,32);ctx.quadraticCurveTo(34,34,32,49);ctx.quadraticCurveTo(30,34,15,32);ctx.quadraticCurveTo(30,30,32,15);ctx.fill();const texture=new THREE.CanvasTexture(canvas);const count=80,positions=new Float32Array(count*3),colors=new Float32Array(count*3),pool=Array.from({length:count},()=>({life:0,x:1000,y:0,z:0,vx:0,vy:0,vz:0,r:1,g:1,b:1}));positions.fill(1000);const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));const mesh=new THREE.Points(geometry,new THREE.PointsMaterial({map:texture,size:.055,vertexColors:true,transparent:true,opacity:.85,blending:THREE.AdditiveBlending,depthWrite:false}));mesh.name='key-sparkles';mesh.frustumCulled=false;let cursor=0,seed=17;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
 return {mesh,emit(x,y,z,color){const c=new THREE.Color(color);for(let i=0;i<5;i++){const p=pool[cursor++%count];p.life=.55+random()*.4;p.total=p.life;p.x=x+(random()-.5)*.045;p.y=y;p.z=z+(random()-.5)*.04;p.vx=(random()-.5)*.17;p.vy=.13+random()*.28;p.vz=-.12-random()*.12;p.r=c.r;p.g=c.g;p.b=c.b;}},update(dt,enabled){mesh.visible=enabled;for(let i=0;i<count;i++){const p=pool[i];p.life-=dt;if(p.life<=0){positions[i*3]=1000;continue;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;positions[i*3]=p.x;positions[i*3+1]=p.y;positions[i*3+2]=p.z;const fade=Math.max(0,p.life/p.total);colors[i*3]=p.r*fade;colors[i*3+1]=p.g*fade;colors[i*3+2]=p.b*fade;}geometry.attributes.position.needsUpdate=true;geometry.attributes.color.needsUpdate=true;}};
}
